// Live API adapter. Legacy browser questions remain drafts, never fabricated answers.
let liveQuestions=[];
const apiCall=async(path,options={})=>{const response=await fetch('/v1'+path,{...options,headers:{'content-type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.reason||data.error||'Request failed');return data};
function answerText(answer){return answer?`Best-case scenario: ${answer.best_case}\n\nWhy: ${answer.why}\n\nDeeper why — benefit to humanity: ${answer.deeper_why}\n\nAssumptions: ${answer.assumptions}\n\nSafety notes: ${answer.safety_notes}`:'No AI answer exists for this question yet.'}
allQuestions=()=>[...liveQuestions.map(q=>({...q,answer:answerText(q.answer),local:false,useful:0,voices:0})),...store.get('cg_questions',[]).map(q=>({id:q.id,title:q.question,tags:q.tags||[],local:true,useful:0,voices:0,answer:'Browser draft — this question was never submitted to AI. Submit it again from Ask to generate an answer.'}))];
matchesDictionary=(item,query)=>tokens(query).every(word=>tokens(`${item.title} ${item.tags.join(' ')} ${item.answer}`).some(term=>term.startsWith(word)));
async function refreshLive(){try{liveQuestions=(await apiCall('/questions')).items;renderQuestions()}catch{document.getElementById('resultCount').textContent='Shared questions could not be loaded. Try again.'}}
document.querySelectorAll('textarea').forEach(field=>{field.spellcheck=true;field.lang='en';field.setAttribute('autocorrect','on')});
document.querySelector('#answerDialog .answer-tiers').innerHTML='';
document.querySelector('#answerDialog .assumption').textContent='';
const access=document.createElement('section');access.innerHTML='<label for="inviteCode">Pilot invitation code</label><input id="inviteCode" type="password" autocomplete="off"><div id="turnstileWidget"></div><p id="accessStatus" role="status">Checking pilot access…</p>';
document.querySelector('.ask-card').prepend(access);
let challengeToken='',accessConfig=null;
apiCall('/config').then(config=>{accessConfig=config;document.getElementById('accessStatus').textContent=config.sessions_available?'Enter your pilot code before your first submission.':'Live submissions are awaiting Turnstile configuration. Existing questions remain readable.';if(config.turnstile_site_key){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=()=>turnstile.render('#turnstileWidget',{sitekey:config.turnstile_site_key,callback:token=>challengeToken=token,'expired-callback':()=>challengeToken=''});document.head.append(script)}}).catch(()=>document.getElementById('accessStatus').textContent='Unable to check pilot access.');
async function ensureSession(){try{await apiCall('/session');return}catch{}if(!accessConfig?.sessions_available)throw new Error('Pilot access is awaiting Turnstile configuration. No question has been submitted.');await apiCall('/sessions',{method:'POST',body:JSON.stringify({invite_code:document.getElementById('inviteCode').value,notice_accepted:termsConsent.checked,turnstile_token:challengeToken})})}
function displayAnswer(record){document.getElementById('echoQuestion').textContent=record.title;document.querySelector('#answerDialog .answer-tiers').textContent=answerText(record.answer);document.querySelector('#answerDialog .answer-tiers').style.whiteSpace='pre-wrap';document.querySelector('#answerDialog .assumption').textContent=record.status==='published'?'AI-generated guidance. Check assumptions before acting.':record.status==='generation_failed'?'AI generation failed. No answer has been published.':'Generating your answer…';}
document.getElementById('askBtn').addEventListener('click',async event=>{event.stopImmediatePropagation();const button=event.currentTarget,text=question.value.trim();if(!text||!document.getElementById('humanityIntent').checked){count.textContent='Enter a question and confirm your intent.';return}const check=screenText(text);if(!check.ok){refuse(check.reason);return}button.disabled=true;count.textContent='Submitting…';try{await ensureSession();const tags=(getAskTags().length?getAskTags():suggestTags(text)).map(t=>t.toLowerCase());const created=await apiCall('/questions',{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify({question:text,tags,humanity_intent:true})});dialog.dataset.questionId=created.id;displayAnswer({title:text,status:'pending'});dialog.showModal();for(let attempt=0;attempt<40;attempt++){await new Promise(resolve=>setTimeout(resolve,2000));const record=await apiCall('/questions/'+created.id);displayAnswer(record);if(record.status!=='pending'){await refreshLive();break}if(attempt===39)document.querySelector('#answerDialog .assumption').textContent='Still processing. Refresh Explore shortly; the question has been saved.'}count.textContent='Question submitted.'}catch(error){count.textContent=error.message}finally{button.disabled=false}},true);
renderComments=async id=>{const list=document.getElementById('commentList');list.textContent='Loading discussion…';try{const data=await apiCall('/questions/'+id+'/comments');list.replaceChildren();if(!data.items.length)list.textContent='No comments yet.';data.items.forEach(comment=>{const node=document.createElement('p');node.className='comment';node.textContent=comment.text;list.append(node)})}catch{list.textContent='Discussion is available for published questions.'}};
document.getElementById('postComment').addEventListener('click',async event=>{event.stopImmediatePropagation();const input=document.getElementById('commentInput'),message=document.getElementById('commentMessage'),check=screenText(input.value);if(!check.ok){message.textContent='Comment blocked. Remove abusive language, harmful requests, and identifying details.';return}event.currentTarget.disabled=true;try{await ensureSession();await apiCall('/questions/'+threadDialog.dataset.questionId+'/comments',{method:'POST',body:JSON.stringify({text:input.value})});input.value='';message.textContent='Comment screened and saved.';await renderComments(threadDialog.dataset.questionId)}catch(error){message.textContent=error.message}finally{document.getElementById('postComment').disabled=false}},true);
document.querySelector('.plain-terms').children[2].textContent='Submitted questions, AI answers, and comments are stored on our server. Published questions, answers, and comments are shared with other readers. Optional context stays in this browser.';
document.querySelector('#dataDialog h2').textContent='Your data';
document.querySelector('#dataDialog h2 + p').textContent='Optional context stays in this browser. Submitted questions, answers, and comments are stored on the server. Clearing local data does not delete server contributions. Participation does not enroll you in AI training.';
document.querySelector('.pulse-card').style.display='none';document.querySelector('.topics').style.display='none';
refreshLive();
